Lemma aobj_cw : forall s LB m0 LF m1 O n l h,
  as_RHEAP H s LB m0 -> as_RFS H LF m1 -> aobj LB LF O n -> O <= l -> l <= h -> h <= O + n -> aclient_write_ok H LB (l, h).
Proof.
  intros s LB m0 LF m1 O n l h RH RF AO K1 K2 K3. replace (l, h) with (l, l + (h - l)) by (f_equal; lia).
  exact (proj1 (aobj_write_ok H HH _ _ _ _ _ _ _ RH RF (aobj_sub LB LF O n l (h - l) AO K1 ltac:(lia)))).
Qed.

Definition prep_WN (lo : Z) (sp : word) (ff fp b res : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 128); (sh ff, sh ff + 16); (b + 24, b + 64); (res, res + 40)]%Z.

Definition prep_segN_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi res b : Z) (es : list mbe) (insz n : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (ff fp : Z),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (prep_WN lo sp ff fp b res) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ fresh_frame H LF 1 ff fp
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' res (SrCells b (mb_mid_out b es insz (mb_lasta b es)) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
    /\ AMBmid m' b es insz n (mb_lasta b es)
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.

Hypothesis MEMSET : asan_memset_stmt.

Lemma prep_segN : forall (ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (LF : list fframe) (LB : list block) (s : as_St H)
    (lo shi res b : Z) (es : list mbe) (insz n : Z) (rj : list byte),
  mb_need es insz n = false ->
  stk asegs m lo (bv_unsigned sp) -> lo + MB_PREP_STACK <= bv_unsigned sp -> aceil <= lo -> bv_unsigned sp mod 16 = 0 ->
  mem_inv asegs m -> tp = Z_to_bv 64 ATP -> ACONST m -> athr_cells m -> as_RFS H LF m -> (length LF < AFS_MAXLIVE)%nat ->
  stack0 m lo shi -> bv_unsigned sp <= shi ->
  AMBuf m b es insz -> as_RHEAP H s LB m -> aobj LB LF b 64 -> AMBufOwn LB es ->
  rw_cells asegs m res [CB 40 rj] -> aobj LB LF res 40 -> res mod 8 = 0 -> accessible m res 40 -> mb_off b es res 40 ->
  1 <= n -> insz + n <= 2^26 -> bv_unsigned ra mod 2 = 0 ->
  evt asegs (prep_segN_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF lo shi res b es insz n m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 res) (Z_to_bv 64 b) (Z_to_bv 64 n) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_MB_PREPARE) fc None m (seg_rom asegs)).
