Lemma mb_es_cases : forall es : list mbe, es = [] \/ exists P xl sl, es = P ++ [(xl, sl)].
Proof. intros [|e es']; [left; reflexivity| right]. exact (mb_es_snoc_inv (e :: es') ltac:(discriminate)). Qed.

