Definition prep_W2 (lo spa : Z) (ff fp b res x xl : Z) : list (Z * Z) :=
  [(lo, spa + 184); (b + 8, b + 64); (x, x + 16); (xl, xl + 8); (res, res + 40); (ff, ff + 8); (sh ff, sh ff + 16); (fp, fp + 1)]%Z.

Definition prep_seg2_post (sp gp tp : word) (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (LF : list fframe) (lo shi spa ff fp res b : Z) (es : list mbe) (insz n x : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (prep_W2 lo spa ff fp b res x (mb_lasta b es)) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' res (SrCells b (mb_mid_out b es insz x) (b + 8) (mb_outpos es insz) (mb_mid_outend es insz n))
    /\ AMBmid m' b es insz n x
    /\ as_RFS H LF m' /\ ACONST m' /\ stack0 m' lo shi.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.
Scheme kc__5 := Elimination for Corelib.Init.Logic.False Sort Prop.

Lemma prep_seg2 : forall (sp gp tp : word) (s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word)
    (m : mem) (LF : list fframe) (LB : list block) (s2_ : as_St H) (p : bptr)
    (lo shi spa ff fp res b : Z) (es : list mbe) (insz n x g oe : Z) (gap : list cell) (j0 j32 j128 j160 h32 h80 rj j16 jx : list byte),
  (pcv = Z_to_bv 64 P_A_PREP_ALLOCRET \/ pcv = ret_pc (Z_to_bv 64 P_A_PREP_ALLOCRET)) ->
  mb_need es insz n = true -> g = mb_grow es insz n -> mb_ok es insz -> 1 <= n -> insz + n <= 2^26 ->
  (spa = bv_unsigned sp + -288 \/ spa = bv_unsigned sp + -304) -> spa mod 32 = 0 ->
